use crate::{catalog,deck::{self,DeckDraft},model::*,rules::*,unit_support::*};
fn society(g:&mut Game){g.players[0].society_zone.card=Some(g.make_card("MSBQ02",0));}
fn setup()->Game{let mut g=game();society(&mut g);let c=g.make_card("BQ046",0);g.core_zones.push(crate::core_zone::CoreZone{owner:0,definition:"BQ046".into(),rest:0,card:Some(c)});g}
fn settle(g:&mut Game){for _ in 0..40{if g.pending.is_some()||g.stack.is_empty()&&g.effects.is_empty(){return;}crate::jc029_tests::pass_top(g);}panic!("unsettled");}
fn draft()->DeckDraft{let mut d=deck::preset("watchers").unwrap();d.id="closed-shoggoth50".into();d.name="封闭候选50+1".into();d.description="50张普通牌加独立核心；封闭测试注册表，非官方预组牌表".into();d.updated_at="2026-10-27T00:00:00Z".into();d.society_id=Some("MSBQ02".into());d.core_card_id=Some("BQ046".into());d.cards=[("BQ064",3),("BQ048",3),("BQ050",3),("BQ051",3),("JC125",38)].into_iter().map(|(id,count)|catalog::DeckEntry{card_id:id.into(),count}).collect();d}
fn candidate(d:DeckDraft)->Result<DeckDraft,String>{let mut cards=catalog::catalog().cards.clone();for c in &mut cards{if ["BQ046","BQ048","BQ050","BQ051"].contains(&c.id.as_str()){c.supported=true;}}let mut societies=catalog::catalog().societies.clone();societies.iter_mut().find(|s|s.card.id=="MSBQ02").unwrap().card.supported=true;deck::validate_with_registry(d,&cards,&societies)}
fn natural(seed:u64)->Game{let mut g=Game::new("natural-shoggoth".into(),"LOCAL".into(),"teams".into(),"P0".into(),"watchers".into(),seed).unwrap();for seat in 1..4{g.join(format!("P{seat}"),"watchers".into()).unwrap();}let first=candidate(draft()).unwrap();let mut ds=vec![first];for _ in 1..4{ds.push(deck::preset("watchers").unwrap());}g.start_validated_decks(ds).unwrap();g.drive().unwrap();g}
#[test]
fn shoggoth_closed_registry_construction_checks_50_plus_core_and_twelve_commands(){let d=draft();assert!(deck::validate(d.clone()).is_err());let d=candidate(d).unwrap();assert_eq!(d.cards.iter().map(|e|e.count).sum::<usize>(),50);for case in 0..5{let mut bad=d.clone();match case{0=>bad.core_card_id=None,1=>bad.core_card_id=Some("JC125".into()),2=>bad.cards.iter_mut().find(|e|e.card_id=="BQ048").unwrap().count=2,3=>bad.cards.push(catalog::DeckEntry{card_id:"JC001".into(),count:1}),_=>bad.cards.push(catalog::DeckEntry{card_id:"BQ046".into(),count:1})};assert!(candidate(bad).is_err(),"case {case}");}let mut g=natural(11);assert_eq!(g.core_zones[0].card.as_ref().unwrap().definition,"BQ046");assert_eq!(g.players[0].hand.len()+g.players[0].deck.len(),50);assert_eq!(g.players[0].hand.len(),5);assert!(g.players[0].hand.iter().chain(&g.players[0].deck).all(|c|c.definition!="BQ046"));restore(&mut g);}
#[test]
fn shoggoth_bq050_real_paid_damage_discount_and_society_gate(){let mut g=setup();fund(&mut g,0,"JC042",4);let victim=field(&mut g,"JC032",1);let id=held(&mut g,"BQ050",0);let a=Action{card_id:Some(id.clone()),option:Some("damage".into()),target_id:Some(victim.clone()),..Action::new("play")};let old=g.players[0].society_zone.card.take();reject(&mut g,0,a.clone());g.players[0].society_zone.card=old;let core=g.core_zones[0].card.take().unwrap();g.regions[0].cards.push(core);assert_eq!(g.effective_cost(0,g.players[0].hand.iter().find(|c|c.id==id).unwrap()),1);act(&mut g,0,a);settle(&mut g);assert_eq!(g.resources(0),3);assert_eq!(g.board(&victim).unwrap().1.damage,1);assert_eq!(g.players[0].society_zone.loss_control,1);restore(&mut g);}
#[test]
fn shoggoth_bq050_nonasset_and_failed_loyalty_are_atomic(){let mut g=setup();let id=held(&mut g,"BQ050",0);reject(&mut g,0,Action{card_id:Some(id.clone()),..Action::new("asset")});fund(&mut g,0,"JC056",8);let target=field(&mut g,"JC032",1);reject(&mut g,0,Action{card_id:Some(id),target_id:Some(target),option:Some("damage".into()),..Action::new("play")});}
#[test]
fn shoggoth_honor_fast_action_reduces_only_next_command(){let mut g=setup();g.players[0].honor=1;fund(&mut g,0,"JC042",1);let source=g.players[0].society_zone.card.as_ref().unwrap().id.clone();act(&mut g,0,Action{card_id:Some(source.clone()),ability_id:Some(crate::msbq02::HONOR.into()),..Action::new("activate")});settle(&mut g);assert_eq!(g.players[0].honor,0);let id=held(&mut g,"BQ048",0);act(&mut g,0,Action{card_id:Some(id),option:Some("core".into()),..Action::new("play")});assert_eq!(g.resources(0),1);assert!(g.modifiers.iter().all(|m|m.uses==0));settle(&mut g);let p=g.pending.clone().unwrap();act(&mut g,0,Action{choice_id:Some(p.choice.id),top:Some(p.choice.options.iter().map(|o|o.id.clone()).collect()),bottom:Some(vec![]),..Action::new("choose")});restore(&mut g);}
#[test]
fn shoggoth_bq051_simultaneous_clear_preserves_cores_and_sets_three(){let mut g=setup();fund(&mut g,0,"JC042",5);let core=g.core_zones[0].card.take().unwrap();let core_id=core.id.clone();g.regions[0].cards.push(core);let victim=field(&mut g,"JC032",1);let hidden=field(&mut g,"JC001",0);g.board_mut(&hidden).unwrap().face_down=true;let outside=g.make_card("JC032",1);let outside_id=outside.id.clone();g.regions[1].cards.push(outside);let id=held(&mut g,"BQ051",0);act(&mut g,0,Action{card_id:Some(id),..Action::new("play")});settle(&mut g);assert!(g.board(&victim).is_none()&&g.board(&hidden).is_none());assert!(g.board(&core_id).is_some()&&g.board(&outside_id).is_some());assert_eq!(g.players[0].society_zone.loss_control,3);assert!(g.msbq02_chaos(g.board(&core_id).unwrap().1));restore(&mut g);}
#[test]
fn shoggoth_three_loss_restricts_play_and_paid_reveal_but_not_assets(){let mut g=setup();g.players[0].society_zone.loss_control=3;fund(&mut g,0,"JC056",8);let id=held(&mut g,"JC125",0);reject(&mut g,0,Action{card_id:Some(id.clone()),region:Some(0),..Action::new("deploy")});act(&mut g,0,Action{card_id:Some(id),..Action::new("asset")});let hidden=field(&mut g,"JC125",0);g.board_mut(&hidden).unwrap().face_down=true;reject(&mut g,0,Action{card_id:Some(hidden),..Action::new("reveal")});}
#[test]
fn shoggoth_natural_closed_registry_50plus1_room_commands(){
 use crate::abi112_review_play_tests::Trace;
 let seed=84;let g=natural(seed);
 eprintln!("shoggoth natural construction seed {seed}");
 let mut t=Trace::new_preserving_rng(g,"shoggoth-closed-registry-50plus1".into(),510);
 let mut deployed=false;let mut returned=false;let mut invoked=false;let mut completed=false;
 for _ in 0..900 {
  if let Some(p)=t.room.game.pending.clone(){
   if matches!(p.resolution,ChoiceResolution::Forecast{..}) {let ids=p.choice.options.iter().map(|o|o.id.clone()).collect();t.action(p.seat,Action{choice_id:Some(p.choice.id),top:Some(ids),bottom:Some(vec![]),..Action::new("choose")});if invoked{completed=true;break;}continue;}
   if matches!(p.resolution,ChoiceResolution::CoreReturn{..}){t.choose(vec!["core".into()]);returned=true;continue;}
   let mut ids=p.choice.options.iter().map(|o|o.id.clone()).collect::<Vec<_>>();if p.seat==0{ids.sort_by_key(|id|t.room.game.players[0].hand.iter().find(|c|c.id==*id).map_or(0,|c|usize::from(["BQ048","BQ050","BQ064","BQ051"].contains(&c.definition.as_str()))));}
   ids.truncate(p.choice.min.unwrap_or(0));t.choose(ids);continue;
  }
  assert_eq!(t.room.game.status,"playing");
  let g=&t.room.game;let legal=g.legal_actions(0);let mut wanted=None;
  if !deployed&&g.players[0].assets.len()<3 {
   let gray=g.players[0].assets.iter().any(|c|catalog::card(&c.definition).color=="灰");let reds=g.players[0].assets.iter().filter(|c|catalog::card(&c.definition).color=="红").count();
   wanted=legal.iter().find(|a|a.action.kind=="asset"&&g.players[0].hand.iter().find(|c|Some(&c.id)==a.action.card_id.as_ref()).is_some_and(|c|(!gray&&c.definition=="BQ064")||(reds<2&&(c.definition=="BQ051"||c.definition=="BQ048"&&g.players[0].hand.iter().filter(|h|h.definition=="BQ048").count()>1)))).map(|a|a.action.clone());
  }
  if wanted.is_none()&&!deployed {wanted=legal.iter().find(|a|a.action.kind=="deploy"&&g.core_zones[0].card.as_ref().is_some_and(|c|Some(&c.id)==a.action.card_id.as_ref())).map(|a|a.action.clone());if wanted.is_some(){deployed=true;}}
  if wanted.is_none()&&deployed&&!returned&&g.stack.is_empty(){wanted=legal.iter().find(|a|a.action.kind=="play"&&a.action.option.as_deref()==Some("damage")&&g.players[0].hand.iter().any(|c|c.definition=="BQ050"&&Some(&c.id)==a.action.card_id.as_ref())&&a.action.target_id.as_ref().is_some_and(|id|g.board(id).is_some_and(|(_,c)|c.definition=="BQ046"&&c.owner==0))).map(|a|a.action.clone());}
  if wanted.is_none()&&returned&&!invoked&&g.stack.is_empty(){wanted=legal.iter().find(|a|a.action.kind=="play"&&a.action.option.as_deref()==Some("core")&&g.players[0].hand.iter().any(|c|c.definition=="BQ048"&&Some(&c.id)==a.action.card_id.as_ref())).map(|a|a.action.clone());if wanted.is_some(){invoked=true;}}
  if let Some(a)=wanted{t.action(0,a);}else{t.pass();}
 }
 eprintln!("natural progress deployed={deployed} returned={returned} invoked={invoked} completed={completed} turn={} window={:?} hand={:?} assets={:?}",t.room.game.turn,t.room.game.window,t.room.game.players[0].hand.iter().map(|c|&c.definition).collect::<Vec<_>>(),t.room.game.players[0].assets.iter().map(|c|(&c.definition,c.exhausted)).collect::<Vec<_>>());
 if !(deployed&&returned&&invoked&&completed){if let Ok(path)=std::env::var("SHOGGOTH_NATIVE_OUT"){std::fs::write(format!("{path}.incomplete.json"),serde_json::to_vec_pretty(&t.room).unwrap()).unwrap();}}
 assert!(deployed&&returned&&invoked&&completed);assert_eq!(t.room.game.core_zones[0].rest,1);assert_eq!(t.room.game.players[0].society_zone.loss_control,3);
 let mut value=t.value();for step in value["steps"].as_array_mut().unwrap(){let room=crate::room::RoomEnvelope::from_persisted(step["expected"]["state"].as_str().unwrap()).unwrap();let command=serde_json::from_value(step["command"].clone()).unwrap();let duplicate=room.transition(step["seat"].as_u64().unwrap()as usize,Some(command),0).unwrap();assert_eq!(duplicate.outcome,"rejected");assert!(!duplicate.changed);assert_eq!(duplicate.state,step["expected"]["state"].as_str().unwrap());step["duplicate"]=serde_json::to_value(duplicate).unwrap();}value["construction"]=serde_json::json!({"seed":seed,"deck":draft(),"ordinaryCount":50,"coreCount":1,"admission":"private test registry only; production admission remains closed","initializer":"Game::start_validated_decks; same production initializer after registry validation","noLayoutOrResourceMutation":true});
 if let Ok(path)=std::env::var("SHOGGOTH_NATIVE_OUT"){std::fs::write(path,serde_json::to_vec_pretty(&value).unwrap()).unwrap();}
}
#[test]
fn shoggoth_bq050_both_targets_real_program_and_response_cancel(){for stale in [false,true]{let mut g=setup();fund(&mut g,0,"JC042",4);let victim=field(&mut g,"JC032",1);let card=g.make_card("JC033",1);let att=card.id.clone();g.attachments.push(Attachment{card,host_id:"society:p1".into()});assert!(g.attachment_host_valid(g.attachments.last().unwrap()));let id=held(&mut g,"BQ050",0);act(&mut g,0,Action{card_id:Some(id),option:Some("both".into()),selected:Some(vec![victim.clone(),att.clone()]),..Action::new("play")});if stale{g.remove_dead(&att,RemovalCause::Destroy);}settle(&mut g);assert_eq!(g.board(&victim).unwrap().1.damage,if stale{0}else{1});assert!(!g.attachments.iter().any(|a|a.card.id==att));assert_eq!(g.resources(0),0);restore(&mut g);}}
#[test]
fn shoggoth_core_honor_rest_pays_printed_cost_separately_and_rejects_bad_receipt(){let mut g=setup();g.core_zones[0].rest=1;g.players[0].honor=1;fund(&mut g,0,"JC042",2);fund(&mut g,0,"JC056",1);let id=g.core_zones[0].card.as_ref().unwrap().id.clone();let a=Action{card_id:Some(id),region:Some(0),option:Some("honor-rest".into()),..Action::new("deploy")};reject(&mut g,0,a.clone());g.players[0].honor=2;act(&mut g,0,a);assert_eq!((g.resources(0),g.players[0].honor),(0,0));let mut bad=g.clone();let f=bad.stack.iter_mut().find_map(|i|i.frame.as_mut().filter(|f|f.ability_key=="deploy")).unwrap();if let PaidCost::CoreRestHonor{before,..}=&mut f.already_paid[1]{*before=1;}else{panic!("missing honor receipt");}assert!(Game::from_persisted(&serde_json::to_string(&bad).unwrap()).is_err());settle(&mut g);assert!(g.regions[0].cards.iter().any(|c|c.definition=="BQ046"));restore(&mut g);}
#[test]
fn shoggoth_corrupt_command_and_duplicate_forced_loss_are_rejected(){let mut g=setup();fund(&mut g,0,"JC042",5);let id=held(&mut g,"BQ051",0);act(&mut g,0,Action{card_id:Some(id),..Action::new("play")});for case in 0..3{let mut bad=g.clone();if case==2{let mut duplicate=bad.stack.iter().find(|s|s.frame.as_ref().is_some_and(|f|f.ability_key==crate::msbq02::LOSS)).unwrap().clone();let id=bad.id();duplicate.id=id.clone();duplicate.frame.as_mut().unwrap().frame_id=id;bad.stack.push(duplicate);}else{let item=bad.stack.iter_mut().find(|s|s.card.as_ref().is_some_and(|c|c.definition=="BQ051")).unwrap();if case==0{item.frame=None;}else{let f=item.frame.as_mut().unwrap();f.source.card.definition="JC001".into();f.ability_key="foreign".into();f.steps.clear();}}assert!(Game::from_persisted(&serde_json::to_string(&bad).unwrap()).is_err());let mut room=crate::jc029_tests::envelope(&g);room.game=bad;assert!(crate::room::RoomEnvelope::from_persisted(&serde_json::to_string(&room).unwrap()).is_err());}}
#[test]
fn shoggoth_three_non_task_regions_cannot_trigger_task_victory(){let mut g=setup();for _ in 0..3{let c=g.make_card("DQJC115",0);g.players[0].score_cards.push(c);}g.msbq02_observe_score(0);assert!(!g.effects.iter().any(|e|matches!(e,Effect::Declare{declaration:d}if d.ability.key==crate::msbq02::WIN)));assert_eq!(g.status,"playing");let mut a=crate::msbq02::definition().abilities.remove(2);a.ops=vec![Op::MSBQ02TaskWin{scored:Some(g.players[0].score_cards.clone())}];let source=g.source_snapshot(g.players[0].society_zone.card.as_ref().unwrap(),None);let f=g.make_frame(0,source,&a,vec![],vec![],None);assert!(g.validate_msbq02_frame(&f).is_err());}
#[test]
fn shoggoth_three_loss_deployment_edge_is_explicitly_unimplemented_not_a_printed_ban(){let mut g=setup();g.players[0].society_zone.loss_control=3;fund(&mut g,0,"JC042",3);fund(&mut g,0,"JC056",3);let id=g.core_zones[0].card.as_ref().unwrap().id.clone();let error=g.apply(0,Action{card_id:Some(id),..Action::new("deploy")}).unwrap_err();assert!(error.contains("待裁定")&&error.contains("不是原规则禁止"));}
